const ExcelJS = require('exceljs');

async function main() {
  const workbook = new ExcelJS.Workbook();
  const sheet = workbook.addWorksheet('Page 1 OCR');

  sheet.columns = [
    { header: 'Line', key: 'line', width: 10 },
    { header: 'Text', key: 'text', width: 60 },
  ];

  // Bold the header row
  sheet.getRow(1).font = { bold: true };

  // OCR results from page 1
  sheet.addRow({ line: 1, text: 'Employee Handbook' });
  sheet.addRow({ line: 2, text: 'Welcome to the company. This handbook outlines our policies.' });

  const outputPath = '/workspace/testbed/docs/handbook_ocr.xlsx';
  await workbook.xlsx.writeFile(outputPath);
  console.log(`Excel file created: ${outputPath}`);
}

main().catch(console.error);
